package io.github.miklires.mauction;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class AuctionRepositoryTest{AuctionRepository repo;@BeforeEach void open(){repo=new AuctionRepository("jdbc:h2:mem:"+UUID.randomUUID()+";DB_CLOSE_DELAY=-1");repo.initialize().join();}@AfterEach void close(){repo.close();}@Test void onlyOneBuyerCanReserve(){UUID seller=UUID.randomUUID();Listing listing=repo.create(seller,"Seller",new byte[]{1,2},10,Instant.now().plusSeconds(60)).join();assertEquals(PurchaseResult.Status.RESERVED,repo.reserve(listing.id(),UUID.randomUUID(),"A").join().status());assertEquals(PurchaseResult.Status.NOT_ACTIVE,repo.reserve(listing.id(),UUID.randomUUID(),"B").join().status());}@Test void ownerCannotBuyOwnListing(){UUID seller=UUID.randomUUID();Listing listing=repo.create(seller,"Seller",new byte[]{1},10,Instant.now().plusSeconds(60)).join();assertEquals(PurchaseResult.Status.OWN_LISTING,repo.reserve(listing.id(),seller,"Seller").join().status());}@Test void expiredAndCancelledItemsRemainReturnable(){UUID seller=UUID.randomUUID();Listing expired=repo.create(seller,"Seller",new byte[]{1},10,Instant.now().minusSeconds(1)).join();Listing cancelled=repo.create(seller,"Seller",new byte[]{2},10,Instant.now().plusSeconds(60)).join();assertTrue(repo.cancel(cancelled.id(),seller,false).join().isPresent());assertEquals(Set.of(expired.id(),cancelled.id()),repo.returns(seller).join().stream().map(Listing::id).collect(java.util.stream.Collectors.toSet()));assertTrue(repo.returned(expired.id(),seller).join());assertEquals(List.of(cancelled.id()),repo.returns(seller).join().stream().map(Listing::id).toList());}@Test void soldItemStaysPendingUntilDeliveryIsMarked(){UUID seller=UUID.randomUUID(),buyer=UUID.randomUUID();Listing listing=repo.create(seller,"Seller",new byte[]{3},10,Instant.now().plusSeconds(60)).join();PurchaseResult purchase=repo.reserve(listing.id(),buyer,"Buyer").join();repo.sold(purchase.transactionId(),listing.id()).join();assertEquals(1,repo.pending(buyer).join().size());repo.stage(purchase.transactionId(),"DELIVERED").join();assertTrue(repo.pending(buyer).join().isEmpty());}}
